import React from 'react';
import { Link } from 'react-router-dom';
const Header = () => {
    return (
        <header className="fixed top-0 w-full z-50 flex justify-between items-center px-margin-mobile md:px-margin-desktop py-4 max-w-container-max mx-auto bg-surface dark:bg-surface-dim border-b border-outline-variant dark:border-outline">
            <div className="flex items-center gap-2 cursor-pointer active:opacity-80">
                <Link to="/">
                    <span className="material-symbols-outlined text-primary dark:text-primary-fixed" style={{ fontSize: '24px' }}>shield</span>
                    <span className="font-headline-md text-headline-md font-bold text-primary dark:text-primary-fixed !text-[25px]">TheEntrance</span>
                </Link>
            </div>
        </header>
    );
};

export default Header;
